import{_ as o,C as i,o as n,c as r,a6 as e,E as s}from"./chunks/framework.Bd7kzaCy.js";const b=JSON.parse('{"title":"第三部分　通用结构语法","description":"","frontmatter":{"title":"第三部分　通用结构语法"},"headers":[],"relativePath":"theory/part-03.md","filePath":"theory/part-03.md"}'),c={name:"theory/part-03.md"};function p(h,a,l,d,u,P){const t=i("SectionLesson");return n(),r("div",null,[a[0]||(a[0]=e('<div class="theory-source"><p><a id="part_3"></a></p><h1 id="part-title-3" tabindex="-1">第三部分　通用结构语法 <a class="header-anchor" href="#part-title-3" aria-label="Permalink to &quot;第三部分　通用结构语法 {#part-title-3}&quot;">​</a></h1><p>本部分给出用于讨论广义经验结构世界的共同描述接口。它不是一套“万物同构”的断言，而是一组可被逐项声明、检验、撤回和跨尺度转换的接口。定义层 D0—D3 规定怎样说清对象与状态；U01—U11 规定解释时需要区分哪些结构位置。定义和原语都不因被写入合同而自动成为经验事实。十一原语不被宣称为逻辑独立、唯一或完备的世界分类；任务可以使用充分的子集，也可以说明理由后补充领域变量。经验支持仍由具体资料、G-instance与相应证据程序提供。</p><h2 id="section-3-1" tabindex="-1">3.1　D0 结构对象 <a class="header-anchor" href="#section-3-1" aria-label="Permalink to &quot;3.1　D0 结构对象 {#section-3-1}&quot;">​</a></h2><p>命题：候选结构对象记为 S*=&lt;B,X,R,I,T,SP,K&gt;；零模型N0只在具体检验实例中冻结。</p><p>定义：D0只声明候选对象S*=&lt;B,X,R,I,T,SP,K&gt;：B为边界，X为状态变量，R为关系或转移约束，I为接口，T为时间窗，SP为尺度剖面，K为同一性判据。该声明使对象可被讨论，但不证明对象有效；N0属于具体G-instance的比较合同。</p><p>候选对象写作：</p><p>S*=&lt;B,X,R,I,T,SP,K&gt;</p><p>B 是边界，说明哪些状态与关系被纳入当前对象，哪些留在对象外。</p><p>X 是注册状态变量，而不是“对象全部真实状态”的代名词。</p><p>R 是关系或状态转移约束，须说明端点、方向、时间与适用条件。</p><p>I 是对象与外部发生输入、输出、过滤、传导或转换的接口。</p><p>T 是观察、预测、干预或反馈所使用的时间窗。</p><p>SP 是九轴尺度剖面，记录对象在聚合、空间、时间、组织、因果、观察分辨率、影响、网络拓扑和管辖授权上的位置。</p><p>K 是同一性判据，说明经过哪些变化后仍把它记为同一对象。</p><p>D0只声明本次分析的候选对象。同一对象可以承担不同任务；每次任务另须明确所问目标、期限、环境、允许操作、误差与证据要求，不能从七个对象字段推定它已足以回答所有问题。N0不写入对象向量，而在具体比较主张中明确。对象字段完整不证明分组增益；命名、聚类、边界绘制和叙事连贯不能代替G1证据。已有记录、观察或其他可靠材料可以支持限定的人、机构、事件及关系事实，须注明来源和同一性条件；这些事实不因尚未检验G1而消失，也不自动证明分组有预测增益、统一主体或共同意愿。</p><h2 id="section-3-2" tabindex="-1">3.2　D1 基本状态词 <a class="header-anchor" href="#section-3-2" aria-label="Permalink to &quot;3.2　D1 基本状态词 {#section-3-2}&quot;">​</a></h2><p>命题：变化、运转、存续、演化、解体与修复分别依预先声明的可检测判据使用；演化不蕴含路径、方向或价值；修复须满足K或F，其价值与授权另经N/O审查。</p><p>定义：变化是注册变量在两个观察位置之间出现可检测差异，不承诺原因、持续性或方向；运转是B、R、I、SP与K仍按当前合同成立时X的状态转移；存续是在指定时间窗内当前K持续成立；演化是对象合同中的边界、变量集合、关系、接口、尺度位置或同一性条件沿时间发生可检测且超过已声明波动窗口的变化，定义本身不包含持久留痕、路径依赖、筛选、方向或价值判断；解体是原合同所声明的K不再成立；修复是形成满足预先声明目标同一性判据K或功能判据F的新状态，是否应修复、以何者为目标以及由谁实施须另经N层与O层审查。</p><p>D1 不定义“结构”，也不判断 D0 候选对象是否有效。对象字段完整只完成候选声明；只有通过预注册门槛的 G1-instance，才能相对于复杂度匹配的 N0 给予该对象有限、受 SP/T/K 与外推单元约束的经验支持。变化、运转或存续等状态词的适用，不能反过来充当对象有效性的证明。存续只描述当前 K 在指定窗口内延续，不表示健康、正当、进步或应当继续。</p><p>演化只登记对象合同字段沿时间出现超过预定波动窗的可检测变化；它不蕴含持久留痕、路径依赖、历史决定、筛选机制、方向、成熟度、进步、衰退或价值判断。是否存在历史条件增量，要另检 G3；是否存在变异—差异保留—再生产，要另过 C8/CM-SELECTION。演化记录可以成立，而 G3 或筛选机制仍不成立。</p><p>解体是既定 K 不再成立。解体可能意味着对象终止、对象转换或需要重新分类，不自动等于失败。修复是形成满足预先声明目标同一性判据 K* 或功能判据 F* 的新状态；它可以保留旧组件，也可以改变边界、关系、接口和载体，不要求回到历史原样。是否应修复、以何种 K*/F* 为目标、由谁决定以及由谁实施，必须分别接受 N 层与 O 层审查，不能由“修复”这个定义自行授权。</p><h2 id="section-3-3" tabindex="-1">3.3　D2 有效反馈 <a class="header-anchor" href="#section-3-3" aria-label="Permalink to &quot;3.3　D2 有效反馈 {#section-3-3}&quot;">​</a></h2><p>命题：先前状态或输出经通道返回并改变后续状态、转移概率或约束才构成有效反馈</p><p>定义：先前状态或输出经可追踪通道返回，并使后续状态、转移概率、时序或约束相对无返回情形发生可检测差异，称为有效反馈。</p><p>有效反馈至少包含四个可追踪位置：先前状态或输出、返回通道、接收位置、被改变的后续字段。信号被接收、回执被生成、表达被记录或档案被保存，都只证明到达或留痕；只有相对于无返回或通道阻断情形，后续状态、转移概率、时序或约束出现可检测差异，才登记为有效反馈。D2 不保证反馈真实、及时、有益，更不保证它形成学习。</p><p>反馈的作用、稳定性和目标改善须分开。返回已经改变后续状态，可以与振荡、放大或目标偏离并存；固定规则也能够形成反馈，不以参数重训为必要条件。若主张纠偏，须另给目标偏差、增益、执行时延、工作区间与失稳判据；若主张改善，还要评价瞬态峰值、成本与分布。指定线性模型的稳定判据只约束该模型，不能凭“负反馈”一词推广为现实过程必然自稳。</p></div>',1)),s(t,{section:"3.3"}),a[1]||(a[1]=e('<div class="theory-source"><h2 id="section-3-4" tabindex="-1">3.4　D3 尺度变换 <a class="header-anchor" href="#section-3-4" aria-label="Permalink to &quot;3.4　D3 尺度变换 {#section-3-4}&quot;">​</a></h2><p>命题：跨尺度判断必须声明M(SP0→SP1)并记录保留、改变、丢失、算子、误差和适用区间</p><p>定义：尺度变换M(SP0→SP1)记录源与目标尺度剖面、保留变量、改变变量、丢失变量、转换算子、误差及适用区间。每项充分性判断还须指明目标查询或任务族、期限、环境和允许操作；静态答案、动力推进、干预响应与可行行动分别判断。</p><p>尺度变换写作：</p><p>M(SP0→SP1)=&lt;保留变量, 改变变量, 丢失变量, 转换算子, 误差, 适用区间&gt;</p><p>不同尺度沿用同一个词，不构成尺度变换。聚合后的对象不是局部对象的简单放大，总体统计量也不能反向分配给每个局部单元。每次 M 都要说明源与目标尺度、对象 K 是否保持、关系或单位怎样转换、哪些信息丢失，以及误差何时超过适用范围；没有桥接证据时，只能并列描述两个尺度，不能宣称迁移成功。</p><p>对同一映射至少区分三种问题：它是否足以回答当前静态查询，是否能够独立推进下一步状态，是否仍足以评价允许的干预。三者没有自动递进关系。一个总量可以精确回答总量问题，同时遗漏局部过载；补入最大值可以恢复某个静态答案，仍可能遗漏定向操作所需的位置身份。因而，映射的成功总要注明目标、期限、环境和允许动作，不能只注明“保留信息”。</p><h3 id="section-3-4-1" tabindex="-1">3.4.1　表示与表述转义 <a class="header-anchor" href="#section-3-4-1" aria-label="Permalink to &quot;3.4.1　表示与表述转义 {#section-3-4-1}&quot;">​</a></h3><p>表示转义，是把有来源的状态、信息或模型表达，经具名转换者、桥接者或规则，重写为面向目标尺度、圈层、任务或词汇系统的新表示；当载荷主要是语言、制度文本或解释时，称为表述转义。新表示必须保留父记录和来源谱系。</p><p>转义不同于尺度变换、圈层关系变换、网络传播、压缩和横向类比迁移。上述操作可以参与一次转义，但不能代替转义合同。转义是否实际改变目标理解或行动，仍需指定通道材料；被折叠差异是否仍有条件增量、不同顺序是否非交换，仍由现有尺度闭合合同检验。</p><p>一次转义最低登记：源表述及语境、目标圈层与任务、转换者或规则及版本、保持项、允许改变、折叠差异、遗漏、新增解释、歧义、误差、父记录、返回源记录的路径、目标侧复核、有效期、失败与撤回条件。目标侧没有独立复核时，只能登记待检验转义。</p><h2 id="section-3-5" tabindex="-1">3.5　十一个通用结构原语 <a class="header-anchor" href="#section-3-5" aria-label="Permalink to &quot;3.5　十一个通用结构原语 {#section-3-5}&quot;">​</a></h2><h3 id="section-3-5-1" tabindex="-1">3.5.1　U01 候选对象接口 <a class="header-anchor" href="#section-3-5-1" aria-label="Permalink to &quot;3.5.1　U01 候选对象接口 {#section-3-5-1}&quot;">​</a></h3><p>U01只登记D0候选对象S*=&lt;B,X,R,I,T,SP,K&gt;及其尺度可追踪性；N0在具体G-instance中冻结，完成U01不预保证G1成立。</p><p>U01 的功能是把一个想研究的对象转成可追踪输入：对象实例 ID 与七个 D0 字段必须完整，进入经验判断时再建立根实例合同。它允许软边界、短时对象、多中心和分布式形式，但不把这些形式预先判为有效。拒绝声明经验字段的纯形而上对象不适用 U01；完成 U01 只允许登记候选对象和生成待检验问题，不生成价值、责任、选择或行动授权。</p><h3 id="section-3-5-2" tabindex="-1">3.5.2　U02 边界与接口 <a class="header-anchor" href="#section-3-5-2" aria-label="Permalink to &quot;3.5.2　U02 边界与接口 {#section-3-5-2}&quot;">​</a></h3><p>边界区分对象内外，接口记录跨界交换和约束。边界可以渗透、移动、嵌套或重叠；接口可以过滤、延迟、转换或阻断跨界过程。空间邻近不自动构成共同边界，存在边界也不意味着封闭，存在接口更不意味着某一方拥有控制权。跨尺度时应保留内外区分与通道的可追踪性，同时允许边界和接口重组；无法声明任何内外区分的对象不适用这一原语。</p><h3 id="section-3-5-3" tabindex="-1">3.5.3　U03 状态与可观察量 <a class="header-anchor" href="#section-3-5-3" aria-label="Permalink to &quot;3.5.3　U03 状态与可观察量 {#section-3-5-3}&quot;">​</a></h3><p>状态以声明的变量和可观察量描述，并保留测量位置与误差。状态是对象在给定 T 与分辨率下的注册配置，可观察量是状态经测量通道形成的记录。可测量量不等于全部状态，未观测不等于不存在，记录还可能包含测量过程自身的贡献。尺度变化可以改变分辨率与可观察量，但变量定义、测量位置和误差必须随迁移保留。</p><h3 id="section-3-5-4" tabindex="-1">3.5.4　U04 组件、载体与基质 <a class="header-anchor" href="#section-3-5-4" aria-label="Permalink to &quot;3.5.4　U04 组件、载体与基质 {#section-3-5-4}&quot;">​</a></h3><p>结构实现须区分组件、承载因果转移的载体与提供实现条件的基质。组件是当前对象的构成单元；载体是指定状态转移实际经过的物质、信息或关系位置；基质提供该实现得以发生的背景条件。同一组件可以不是关键载体，组件替换后对象也可能保持 K。识别载体只说明实现位置，不能赋予载体意图、责任或继续承载的义务；不主张经验实现的纯定义对象不适用该原语。</p><h3 id="section-3-5-5" tabindex="-1">3.5.5　U05 关系与约束 <a class="header-anchor" href="#section-3-5-5" aria-label="Permalink to &quot;3.5.5　U05 关系与约束 {#section-3-5-5}&quot;">​</a></h3><p>关系只有在改变可行状态或转移时才作为结构约束登记。关系描述端点间的可重复依赖，约束缩小可行状态或转移集合。相关、相邻和同时出现不能自行升级为因果约束，因果提升还需要时间顺序、指定通道、干预或反事实。约束存在也不证明它正当。尺度变换可能改变有效关系，因而关系端点、方向和适用窗必须可追踪。</p><h3 id="section-3-5-6" tabindex="-1">3.5.6　U06 流、通道与传导 <a class="header-anchor" href="#section-3-5-6" aria-label="Permalink to &quot;3.5.6　U06 流、通道与传导 {#section-3-5-6}&quot;">​</a></h3><p>在主张跨组件或跨边界转移的系统中，流说明资源、信号或作用的对象、方向、速率与分布，通道说明承载路径，传导说明输入怎样改变下游状态。容量、时延、可靠性、可控性和损耗是逐通道、逐维度测量的候选属性，未测维度保持未知。U06 提供描述位置，不证明任何特定通道真实存在；通道效应仍需 G2-instance。源、目标和通道要在尺度变换中保持可追踪，通道也不能被自动认定为责任主体。</p><h3 id="section-3-5-7" tabindex="-1">3.5.7　U07 反馈与状态更新 <a class="header-anchor" href="#section-3-5-7" aria-label="Permalink to &quot;3.5.7　U07 反馈与状态更新 {#section-3-5-7}&quot;">​</a></h3><p>先前状态或输出经通道返回并改变后续状态、概率或约束，才是有效反馈。反馈是返回关系，状态更新是返回或其他输入造成的后续变化；二者需要分别登记。反馈可以强化、抑制、延迟、失真或被阻断。有效反馈不等于学习，也不等于修复：C3的载体学习分支按§4.5核对当前更新、后续调用和任务结果；C3-learning/CM-LEARNING-history这一历史增量分支还需要可保留更新、重复轮次与 G3 的历史条件增量（参见§6.3）；修复还需要 K*/F* 以及 N/O 审查。没有返回通道的单向过程不适用 U07。</p><h3 id="section-3-5-8" tabindex="-1">3.5.8　U08 条件与环境 <a class="header-anchor" href="#section-3-5-8" aria-label="Permalink to &quot;3.5.8　U08 条件与环境 {#section-3-5-8}&quot;">​</a></h3><p>环境和条件只有通过可检测接口改变对象状态或转移时进入解释。条件是某一机制在当前实例成立所需的局部前提；环境是被留在当前边界之外、但可能通过接口影响对象的变量集合。环境不是一个拟人化的总原因，也不决定全部结果。尺度变化会重画对象—环境边界，因此相关环境变量与作用接口必须重新声明；明确封闭且无外部通道的模型可把该原语标为不适用。</p><h3 id="section-3-5-9" tabindex="-1">3.5.9　U09 负荷、容量与恢复余量 <a class="header-anchor" href="#section-3-5-9" aria-label="Permalink to &quot;3.5.9　U09 负荷、容量与恢复余量 {#section-3-5-9}&quot;">​</a></h3><p>在存在持续通量、维护或恢复要求的非平衡系统中，负荷须与有限容量和恢复余量共同描述。负荷是给定窗口与位置上的同型需求，容量是相同类型或具有明确转换映射的可承接范围，恢复余量是扰动后仍可用于补给、重组或回到目标 K/F 的空间。三者都要声明单位、分布、窗口和瓶颈位置。瞬时缺口不自动等于累积损伤，过载也不生成继续承载的义务；不存在持续非平衡或维护要求的对象可标为不适用。</p><h3 id="section-3-5-10" tabindex="-1">3.5.10　U10 留痕、记忆与路径 <a class="header-anchor" href="#section-3-5-10" aria-label="Permalink to &quot;3.5.10　U10 留痕、记忆与路径 {#section-3-5-10}&quot;">​</a></h3><p>留痕是先前变化在状态、关系、边界、接口、转移约束或环境中形成的持久记录；痕迹只有在进入后续转移时才作为结构记忆，只有历史项在控制当前注册状态后改变未来路径、概率或转换成本时，才按G3登记历史增量型路径差异。已测当前载体传递的一般历史作用另按§4.5检验；痕迹保存不等于 G3 成立，路径差异也不等于命运或不可修复。痕迹载体与持久阈值可随尺度改变；无时间延展的静态分类不适用 U10。</p><h3 id="section-3-5-11" tabindex="-1">3.5.11　U11 相位、转移与解体 <a class="header-anchor" href="#section-3-5-11" aria-label="Permalink to &quot;3.5.11　U11 相位、转移与解体 {#section-3-5-11}&quot;">​</a></h3><p>相位是同一 K 下、由预先登记变量与判据区分的条件性运转区间；转移是区间间超过噪声和分箱敏感性的可检测变化；解体只表示原 K 不再成立。基础相位模式不要求路径依赖，指定触发因果另需G2。当前载体传递的持续效应或迟恢复按§4.5另取证；主张当前表示之外的历史条件增量时，才另需G3。相位不是 S0—S6 的成熟度排名，也不是所有对象必经的阶段；若转移前 K 已失效，应改记为对象转换或解体。</p><h2 id="section-3-6" tabindex="-1">3.6　原语的组合与按用途闭合 <a class="header-anchor" href="#section-3-6" aria-label="Permalink to &quot;3.6　原语的组合与按用途闭合 {#section-3-6}&quot;">​</a></h2><p>U01—U03 回答“当前把什么当作候选对象、怎样看见它”；U04—U06 回答“结构由什么实现、变化经何处传导”；U07—U10 回答“返回怎样更新状态、条件怎样作用、负荷怎样分布、历史怎样留下效应”；U11 回答“何时仍是同一运转区间，何时转移、转换或解体”。</p><p>这些原语互为接口，而不是互相证明。任何缺失字段必须标为未知、不适用、不可观察或为保护而不公开，并说明该状态对结论上限的影响；不得用自然语言的熟悉感补齐合同，也不得把某个原语的存在直接升级为阶段、价值、责任、选择或授权。</p></div>',1))])}const q=o(c,[["render",p]]);export{b as __pageData,q as default};
